//! Persistent, accent-folded subtitle search. The renderer retains its established ranking/highlights.
use std::path::Path;
use rusqlite::{Connection,params,OptionalExtension};
use serde_json::Value;
use tauri::Manager;
fn connection(app:&tauri::AppHandle)->Result<Connection,String>{let path=app.path().app_local_data_dir().map_err(|e|e.to_string())?.join("luna-library.sqlite3");let db=Connection::open(path).map_err(|e|e.to_string())?;db.busy_timeout(std::time::Duration::from_secs(5)).map_err(|e|e.to_string())?;db.execute_batch("CREATE TABLE IF NOT EXISTS subtitle_index(path TEXT PRIMARY KEY,subtitle TEXT NOT NULL,stamp TEXT NOT NULL,entry TEXT NOT NULL); CREATE VIRTUAL TABLE IF NOT EXISTS subtitle_fts USING fts5(path UNINDEXED,fold,tokenize='trigram');").map_err(|e|e.to_string())?;Ok(db)}
fn stamp(path:&str)->Result<String,String>{let meta=std::fs::metadata(path).map_err(|e|e.to_string())?;if !meta.is_file(){return Err("Subtitle file missing".into());}let modified=meta.modified().map_err(|e|e.to_string())?.duration_since(std::time::UNIX_EPOCH).map_err(|e|e.to_string())?.as_nanos();Ok(format!("v2:{}:{modified}",meta.len()))}
#[tauri::command]pub async fn database_lines_get(app:tauri::AppHandle,path:String,subtitle:String)->Result<Value,String>{crate::blocking(move||{let db=connection(&app)?;let stamp=stamp(&subtitle)?;let raw:Option<String>=db.query_row("SELECT entry FROM subtitle_index WHERE path=?1 AND subtitle=?2 AND stamp=?3",params![path,subtitle,stamp],|r|r.get(0)).optional().map_err(|e|e.to_string())?;let entry=raw.map(|s|serde_json::from_str::<Value>(&s).map_err(|e|e.to_string())).transpose()?;Ok(serde_json::json!({"stamp":stamp,"entry":entry}))}).await}
#[tauri::command]pub async fn database_lines_put(app:tauri::AppHandle,path:String,subtitle:String,entry:Value,expected_stamp:String)->Result<(),String>{
    crate::blocking(move||{if !Path::new(&path).is_file()||entry["path"]!=path{return Err("Invalid subtitle index path".into());}let lines=entry["lines"].as_array().ok_or("Invalid subtitle index")?;if lines.len()>30000{return Err("Subtitle index is too large".into());}let mut fold=String::new();for line in lines{if !line["start"].as_f64().is_some_and(|n|n.is_finite()&&n>=0.0){return Err("Invalid subtitle timestamp".into());}let text=line["fold"].as_str().ok_or("Missing folded subtitle text")?;if text.len()>10000{return Err("Subtitle line too long".into());}fold.push_str(text);fold.push(' ');}let raw=serde_json::to_string(&entry).map_err(|e|e.to_string())?;if raw.len()>8_000_000{return Err("Subtitle index is too large".into());}let stamp=stamp(&subtitle)?;if stamp!=expected_stamp{return Err("Subtitle changed while indexing; reopen search to refresh".into());}let mut db=connection(&app)?;let tx=db.transaction().map_err(|e|e.to_string())?;tx.execute("INSERT INTO subtitle_index(path,subtitle,stamp,entry) VALUES(?1,?2,?3,?4) ON CONFLICT(path) DO UPDATE SET subtitle=excluded.subtitle,stamp=excluded.stamp,entry=excluded.entry",params![path,subtitle,stamp,raw]).map_err(|e|e.to_string())?;tx.execute("DELETE FROM subtitle_fts WHERE path=?1",[&path]).map_err(|e|e.to_string())?;tx.execute("INSERT INTO subtitle_fts(path,fold) VALUES(?1,?2)",params![path,fold]).map_err(|e|e.to_string())?;tx.commit().map_err(|e|e.to_string())}).await
}
#[tauri::command]pub async fn database_lines_search(app:tauri::AppHandle,tokens:Vec<String>,paths:Vec<String>)->Result<Vec<String>,String>{
    if paths.len()>2000||paths.iter().any(|p|p.len()>32768){return Err("Too many subtitle paths".into());}
    if tokens.len()>12||tokens.iter().any(|t|t.len()>512){return Err("Search query too long".into());}let terms:Vec<String>=tokens.into_iter().filter(|s|s.chars().count()>=3).map(|s|format!("\"{}\"",s.replace('"',"\"\""))).collect();if terms.is_empty(){return Ok(Vec::new());}
    crate::blocking(move||{let db=connection(&app)?;let mut stmt=db.prepare("SELECT path FROM subtitle_fts WHERE subtitle_fts MATCH ?1 AND path IN (SELECT value FROM json_each(?2)) ORDER BY rank LIMIT 2000").map_err(|e|e.to_string())?;stmt.query_map(params![terms.join(" OR "),serde_json::to_string(&paths).map_err(|e|e.to_string())?],|r|r.get::<_,String>(0)).map_err(|e|e.to_string())?.collect::<Result<Vec<_>,_>>().map_err(|e|e.to_string())}).await
}
